{
  "findings": [
    {
      "check_id": "CKV_GCP_68",
      "title": "Pub/Sub topic lacks encryption with a customer-managed key (CMK)",
      "resource": "google_pubsub_topic.notification_trigger",
      "severity": "MEDIUM",
      "explanation": "The Pub/Sub topic does not specify a customer-managed encryption key (CMK). Without CMK, Google-managed encryption is used, which may not meet compliance or organizational security requirements."
    }
  ],
  "patched_code": "resource \"google_pubsub_topic\" \"notification_trigger\" {\n  name       = \"enterprise-disaster-recovery-orchestration-platform-topic-notification\"\n  kms_key_name = \"projects/my-project/locations/global/keyRings/my-keyring/cryptoKeys/my-key\"\n}",
  "fix_summary": "Added a customer-managed encryption key (CMK) to the Pub/Sub topic to enhance data security and meet compliance requirements."
}
